    private void mergeMetric(final String metricName, final double metricValue) {
        // Check that the metric name and value are not null
        if (metricName == null || metricValue == null) {
            throw new IllegalArgumentException("Metric name and value cannot be null");
        }
        // Merge the metric value
        Double currentMetricValue = get(metricName);
        if (currentMetricValue != null) {
            set(metricName, currentMetricValue + metricValue);
        } else {
            set(metricName, metricValue);
        }
    }

