public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }

    final int byteCount = str.length() * 3;
    final byte[] buf = new byte[byteCount];
    int i;
    int j = 0;

    for (i = 0; i < str.length(); i++) {
        final char ch = str.charAt(i);

        if (ch < 0x80) {
            buf[j++] = (byte) ch;
        } else if (ch < 0x800) {
            buf[j++] = (byte) (0xC0 | (ch >> 6));
            buf[j++] = (byte) (0x80 | (ch & 0x3F));
        } else {
            buf[j++] = (byte) (0xE0 | (ch >> 12));
            buf[j++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
            buf[j++] = (byte) (0x80 | (ch & 0x3F));
        }
    }

    final boolean success = session.write(lb.memorySegment, 0, buf, 0, byteCount, 0);
    if (!success) {
        throw new RuntimeException("Failed to write to the linked buffer");
    }
    return lb;
}

