public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line into a thread snapshot
            ThreadSnapshot threadSnapshot = parseLine(line, timeRanges);
            if (threadSnapshot != null) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

private static ThreadSnapshot parseLine(String line, List<ProfileAnalyzeTimeRange> timeRanges) {
    // Split the line into individual fields
    String[] fields = line.split(",");
    if (fields.length != 3) {
        return null;
    }

    // Check if the time range matches one of the defined ranges
    long ts = Long.parseLong(fields[0]);
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (ts >= timeRange.getStartTime() && ts <= timeRange.getEndTime()) {
            return new ThreadSnapshot(ts, fields[1], fields[2]);
        }
    }
    return null;
}
